solution.code:
const MENIT_FOKUS = 25;
const MENIT_ISTIRAHAT = 5;

async function pasangAturan(aktif) {
  const lama = await chrome.declarativeNetRequest.getDynamicRules();
  const { situs } = await chrome.storage.sync.get({ situs: [] });
  const baru = aktif
    ? situs.map((domain, i) => ({
        id: i + 1,
        priority: 1,
        action: { type: "redirect", redirect: { extensionPath: "/blocked.html" } },
        condition: { requestDomains: [domain], resourceTypes: ["main_frame"] },
      }))
    : [];
  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: lama.map((r) => r.id),
    addRules: baru,
  });
}

async function mulai() {
  const berakhir = Date.now() + MENIT_FOKUS * 60000;
  await chrome.storage.local.set({ mode: "fokus", berakhir });
  await chrome.alarms.clear("istirahat");
  await chrome.alarms.create("fokus", { delayInMinutes: MENIT_FOKUS });
  await pasangAturan(true);
  await chrome.action.setBadgeText({ text: MENIT_FOKUS + "m" });
  return { ok: true };
}

async function status() {
  const { mode, berakhir } = await chrome.storage.local.get({ mode: "diam", berakhir: 0 });
  if (mode === "diam") return { mode, sisaMenit: 0 };
  const sisaMenit = Math.max(0, Math.ceil((berakhir - Date.now()) / 60000));
  return { mode, sisaMenit };
}

async function berhenti() {
  await chrome.storage.local.set({ mode: "diam", berakhir: 0 });
  await chrome.alarms.clear("fokus");
  await chrome.alarms.clear("istirahat");
  await pasangAturan(false);
  await chrome.action.setBadgeText({ text: "" });
  return { ok: true };
}

async function saatAlarm(alarm) {
  if (alarm.name === "fokus") {
    await chrome.storage.local.set({ mode: "istirahat", berakhir: Date.now() + MENIT_ISTIRAHAT * 60000 });
    await pasangAturan(false);
    await chrome.alarms.create("istirahat", { delayInMinutes: MENIT_ISTIRAHAT });
    await chrome.action.setBadgeText({ text: MENIT_ISTIRAHAT + "m" });
    await chrome.notifications.create("fokus-selesai", {
      type: "basic",
      iconUrl: "icons/icon128.png",
      title: "Sesi fokus selesai",
      message: "Istirahat 5 menit dulu, ya.",
    });
  } else if (alarm.name === "istirahat") {
    await chrome.storage.local.set({ mode: "diam", berakhir: 0 });
    await chrome.action.setBadgeText({ text: "" });
    await chrome.notifications.create("istirahat-selesai", {
      type: "basic",
      iconUrl: "icons/icon128.png",
      title: "Istirahat selesai",
      message: "Siap fokus lagi? Tekan Mulai di popup.",
    });
  }
}

function pasangListener() {
  chrome.runtime.onMessage.addListener((pesan, sender, sendResponse) => {
    let kerja;
    switch (pesan?.tipe) {
      case "mulai": kerja = mulai(); break;
      case "status": kerja = status(); break;
      case "berhenti": kerja = berhenti(); break;
      default:
        sendResponse({ ok: false });
        return false;
    }
    kerja.then(sendResponse);
    return true;
  });
  chrome.alarms.onAlarm.addListener(saatAlarm);
}

project.setup:
// chrome tiruan untuk latihan (bukan API asli). Helper berawalan _ hanya untuk tes.
const chrome = (() => {
  const salin = (v) => (v === undefined ? undefined : JSON.parse(JSON.stringify(v)));
  const semuaEvent = [];
  const event = () => {
    const e = {
      _fs: [],
      addListener(f) { e._fs.push(f); },
      removeListener(f) { e._fs = e._fs.filter((x) => x !== f); },
      hasListener(f) { return e._fs.includes(f); },
      _picu(...args) { return Promise.all(e._fs.map((f) => f(...args))); },
    };
    semuaEvent.push(e);
    return e;
  };
  const jam = { t: 1767600000000, sekarang() { return jam.t; }, maju(menit) { jam.t += menit * 60000; } };
  Date.now = () => jam.t;
  const c = { _jam: jam, _restart() { for (const e of semuaEvent) e._fs = []; } };
  const onChanged = event();
  const area = (nama, isi, kuota) => ({
    ...kuota,
    async get(keys) {
      if (keys == null) return salin(isi);
      if (typeof keys === "string") keys = [keys];
      const hasil = Array.isArray(keys) ? {} : salin(keys);
      for (const k of Array.isArray(keys) ? keys : Object.keys(keys)) if (k in isi) hasil[k] = salin(isi[k]);
      return hasil;
    },
    async set(obj) {
      const ubah = {};
      for (const [k, v] of Object.entries(salin(obj))) {
        if (JSON.stringify(isi[k]) === JSON.stringify(v)) continue;
        ubah[k] = k in isi ? { oldValue: isi[k], newValue: v } : { newValue: v };
        isi[k] = v;
      }
      if (Object.keys(ubah).length) onChanged._fs.forEach((f) => f(salin(ubah), nama));
    },
    async remove(keys) {
      const ubah = {};
      for (const k of [].concat(keys)) if (k in isi) { ubah[k] = { oldValue: isi[k] }; delete isi[k]; }
      if (Object.keys(ubah).length) onChanged._fs.forEach((f) => f(salin(ubah), nama));
    },
    async clear() { await this.remove(Object.keys(isi)); },
  });
  c.storage = {
    local: area("local", {}, { QUOTA_BYTES: 10485760 }),
    sync: area("sync", {"situs": ["youtube.com", "instagram.com"]}, { QUOTA_BYTES: 102400, QUOTA_BYTES_PER_ITEM: 8192, MAX_ITEMS: 512 }),
    session: area("session", {}, { QUOTA_BYTES: 10485760 }),
    onChanged,
  };
  const alarm = new Map();
  const onAlarm = event();
  c.alarms = {
    async create(nama, info) {
      if (typeof nama === "object" && nama !== null) { info = nama; nama = ""; }
      nama = nama ?? "";
      const menit = info.delayInMinutes ?? info.periodInMinutes;
      if (info.when == null && menit == null) throw new Error("Alarm butuh when, delayInMinutes, atau periodInMinutes");
      const a = { name: nama, scheduledTime: info.when ?? jam.t + menit * 60000 };
      if (info.periodInMinutes != null) a.periodInMinutes = info.periodInMinutes;
      alarm.set(nama, a);
    },
    async get(nama = "") { return salin(alarm.get(nama)); },
    async getAll() { return salin([...alarm.values()]); },
    async clear(nama = "") { return alarm.delete(nama); },
    async clearAll() { const ada = alarm.size > 0; alarm.clear(); return ada; },
    onAlarm,
  };
  c._picu = async (nama) => {
    const a = alarm.get(nama);
    if (!a) return false;
    const dikirim = salin(a);
    if (a.periodInMinutes == null) alarm.delete(nama);
    else a.scheduledTime += a.periodInMinutes * 60000;
    await onAlarm._picu(dikirim);
    return true;
  };
  const onMessage = event();
  const onInstalled = event();
  c.runtime = {
    id: "idtiruanekstensi",
    onMessage,
    onInstalled,
    onStartup: event(),
    async sendMessage() { throw new Error("Latihan ini memakai chrome._kirim(pesan) untuk meniru pesan dari popup"); },
  };
  c._instal = (reason = "install") => onInstalled._picu({ reason });
  c._kirim = async (pesan, sender = { id: "idtiruanekstensi", url: "chrome-extension://idtiruanekstensi/popup.html" }) => {
    if (!onMessage._fs.length) throw new Error("Could not establish connection. Receiving end does not exist.");
    let selesai = false, balasan;
    const sendResponse = (r) => { if (!selesai) { selesai = true; balasan = salin(r); } };
    let tunggu = false;
    for (const f of onMessage._fs) if (f(salin(pesan), salin(sender), sendResponse) === true) tunggu = true;
    // ponytail: tanpa setTimeout di sandbox, balasan asinkron ditunggu lewat 5000 putaran microtask
    for (let i = 0; tunggu && !selesai && i < 5000; i++) await null;
    return balasan;
  };
  c._badge = { text: "", color: null };
  c.action = {
    async setBadgeText({ text }) { c._badge.text = text ?? ""; },
    async getBadgeText() { return c._badge.text; },
    async setBadgeBackgroundColor({ color }) { c._badge.color = color; },
  };
  c._notif = [];
  c.notifications = {
    async create(id, opsi) {
      if (typeof id === "object" && id !== null) { opsi = id; id = undefined; }
      id = id ?? "notif-" + (c._notif.length + 1);
      c._notif.push({ id, ...salin(opsi) });
      return id;
    },
    async clear(id) { const n = c._notif.length; c._notif = c._notif.filter((x) => x.id !== id); return c._notif.length < n; },
  };
  const aturan = { dynamic: [], session: [] };
  const ubahAturan = (jenis) => async ({ removeRuleIds = [], addRules = [] } = {}) => {
    const sisa = aturan[jenis].filter((r) => !removeRuleIds.includes(r.id));
    const id = new Set(sisa.map((r) => r.id));
    for (const r of addRules) {
      if (!Number.isInteger(r.id) || r.id < 1) throw new Error("Rule id must be a positive integer");
      if (id.has(r.id)) throw new Error("Rule with id " + r.id + " does not have a unique ID.");
      id.add(r.id);
    }
    aturan[jenis] = [...sisa, ...salin(addRules)];
  };
  c.declarativeNetRequest = {
    MAX_NUMBER_OF_DYNAMIC_RULES: 30000,
    updateDynamicRules: ubahAturan("dynamic"),
    async getDynamicRules() { return salin(aturan.dynamic); },
    updateSessionRules: ubahAturan("session"),
    async getSessionRules() { return salin(aturan.session); },
  };
  return c;
})();

function sama(a, b) {
  return JSON.stringify(a) === JSON.stringify(b);
}

async function aturan() {
  return chrome.declarativeNetRequest.getDynamicRules();
}

async function lokal() {
  return chrome.storage.local.get(null);
}

