solution.code:
function versiValid(v) {
  if (typeof v !== "string") return false;
  const bagian = v.split(".");
  if (bagian.length < 1 || bagian.length > 4) return false;
  return bagian.every((b) => /^(0|[1-9]\d*)$/.test(b) && Number(b) <= 65535);
}

function cekManifest(m) {
  const salah = [];
  if (m.manifest_version !== 3) salah.push("manifest_version");
  if (typeof m.name !== "string" || m.name.trim() === "") salah.push("name");
  if (!versiValid(m.version)) salah.push("version");
  if (m.background !== undefined && typeof m.background?.service_worker !== "string") salah.push("background.service_worker");
  const popup = m.action?.default_popup;
  if (popup !== undefined && !(typeof popup === "string" && popup.endsWith(".html"))) salah.push("action.default_popup");
  return salah;
}

