// chrome tiruan untuk latihan (bukan API asli). Helper berawalan _ hanya untuk tes.
const chrome = (() => {
  const salin = (v) => (v === undefined ? undefined : JSON.parse(JSON.stringify(v)));
  const semuaEvent = [];
  const event = () => {
    const e = {
      _fs: [],
      addListener(f) { e._fs.push(f); },
      removeListener(f) { e._fs = e._fs.filter((x) => x !== f); },
      hasListener(f) { return e._fs.includes(f); },
      _picu(...args) { return Promise.all(e._fs.map((f) => f(...args))); },
    };
    semuaEvent.push(e);
    return e;
  };
  const jam = { t: 1767600000000, sekarang() { return jam.t; }, maju(menit) { jam.t += menit * 60000; } };
  Date.now = () => jam.t;
  const c = { _jam: jam, _restart() { for (const e of semuaEvent) e._fs = []; } };
  const onChanged = event();
  const area = (nama, isi, kuota) => ({
    ...kuota,
    async get(keys) {
      if (keys == null) return salin(isi);
      if (typeof keys === "string") keys = [keys];
      const hasil = Array.isArray(keys) ? {} : salin(keys);
      for (const k of Array.isArray(keys) ? keys : Object.keys(keys)) if (k in isi) hasil[k] = salin(isi[k]);
      return hasil;
    },
    async set(obj) {
      const ubah = {};
      for (const [k, v] of Object.entries(salin(obj))) {
        if (JSON.stringify(isi[k]) === JSON.stringify(v)) continue;
        ubah[k] = k in isi ? { oldValue: isi[k], newValue: v } : { newValue: v };
        isi[k] = v;
      }
      if (Object.keys(ubah).length) onChanged._fs.forEach((f) => f(salin(ubah), nama));
    },
    async remove(keys) {
      const ubah = {};
      for (const k of [].concat(keys)) if (k in isi) { ubah[k] = { oldValue: isi[k] }; delete isi[k]; }
      if (Object.keys(ubah).length) onChanged._fs.forEach((f) => f(salin(ubah), nama));
    },
    async clear() { await this.remove(Object.keys(isi)); },
  });
  c.storage = {
    local: area("local", {}, { QUOTA_BYTES: 10485760 }),
    sync: area("sync", {}, { QUOTA_BYTES: 102400, QUOTA_BYTES_PER_ITEM: 8192, MAX_ITEMS: 512 }),
    session: area("session", {}, { QUOTA_BYTES: 10485760 }),
    onChanged,
  };
  const alarm = new Map();
  const onAlarm = event();
  c.alarms = {
    async create(nama, info) {
      if (typeof nama === "object" && nama !== null) { info = nama; nama = ""; }
      nama = nama ?? "";
      const menit = info.delayInMinutes ?? info.periodInMinutes;
      if (info.when == null && menit == null) throw new Error("Alarm butuh when, delayInMinutes, atau periodInMinutes");
      const a = { name: nama, scheduledTime: info.when ?? jam.t + menit * 60000 };
      if (info.periodInMinutes != null) a.periodInMinutes = info.periodInMinutes;
      alarm.set(nama, a);
    },
    async get(nama = "") { return salin(alarm.get(nama)); },
    async getAll() { return salin([...alarm.values()]); },
    async clear(nama = "") { return alarm.delete(nama); },
    async clearAll() { const ada = alarm.size > 0; alarm.clear(); return ada; },
    onAlarm,
  };
  c._picu = async (nama) => {
    const a = alarm.get(nama);
    if (!a) return false;
    const dikirim = salin(a);
    if (a.periodInMinutes == null) alarm.delete(nama);
    else a.scheduledTime += a.periodInMinutes * 60000;
    await onAlarm._picu(dikirim);
    return true;
  };
  return c;
})();

chapters.body:
## Tujuan

- Membedakan area `local`, `sync`, dan `session` beserta kuotanya.
- Memakai `get` dengan objek default, `set`, `remove`, dan `clear`.
- Menyinkronkan popup dan service worker lewat `chrome.storage.onChanged`.
- Menyimpan state timer sebagai waktu berakhir, bukan sisa detik.

## Buku besar ekstensi

Di bab sebelumnya kamu tahu service worker bisa mati kapan saja dan popup kehilangan semua variabelnya begitu ditutup. Jadi di mana data ekstensi disimpan? Jawabannya **`chrome.storage`**, penyimpanan khusus ekstensi yang bisa dibaca dari service worker, popup, halaman opsi, dan content script.

Kenapa tidak `localStorage` saja? Ada tiga alasan:

- `localStorage` **tidak tersedia** di service worker.
- `localStorage` sinkron dan hanya menyimpan string, sedangkan `chrome.storage` asinkron dan menyimpan data mirip JSON: angka, boolean, array, dan objek.
- `chrome.storage` punya event perubahan yang bisa didengar semua bagian ekstensi.

Semua area butuh izin `"storage"` di manifest.

## Tiga area storage

![Tiga area chrome.storage dan kegunaannya](slide:11)

| Area | Disimpan di | Kuota | Cocok untuk |
| --- | --- | --- | --- |
| `chrome.storage.local` | Perangkat ini | 10 MB | State yang sering berubah, data besar |
| `chrome.storage.sync` | Ikut akun Chrome | 102.400 byte total, 8.192 byte per item, maks 512 item | Pengaturan pengguna |
| `chrome.storage.session` | Memori saja | 10 MB | Data sementara selama browser terbuka |

Beberapa catatan:

- **`sync`** disinkronkan ke perangkat lain yang login dengan akun Chrome yang sama dan menyalakan sinkronisasi. Kuotanya kecil, jadi simpan hanya pengaturan, misalnya daftar situs yang diblokir dan durasi fokus. Kalau sinkronisasi mati, `sync` tetap bisa dipakai dan berperilaku seperti penyimpanan lokal.
- **`local`** bertahan walau browser ditutup, tapi hanya di perangkat itu. Cocok untuk state timer yang berubah tiap sesi.
- **`session`** tersedia sejak Chrome 102 dan hanya ada di memori. Isinya **tetap ada saat service worker tidur**, tapi hilang saat browser ditutup. Secara bawaan area ini tidak bisa dibaca content script.
- Data di `local` dan `sync` hilang bila ekstensi dicopot.

Untuk Fokus Dulu: daftar situs di `sync`, state timer di `local`.

## get dengan objek default

Method `get` menerima beberapa bentuk kunci dan selalu mengembalikan **objek**:

```js
await chrome.storage.local.get("mode");          // { mode: "fokus" } atau {}
await chrome.storage.local.get(["mode", "berakhir"]);
await chrome.storage.local.get(null);            // semua isi
await chrome.storage.sync.get({ situs: [], menitFokus: 25 });
```

Bentuk terakhir paling berguna. Kunci yang belum pernah disimpan diisi nilai default, sedangkan kunci yang sudah ada memakai nilai tersimpan. Jadi kode setelahnya tidak perlu repot memeriksa `undefined`:

```js
const { situs, menitFokus } = await chrome.storage.sync.get({
  situs: [],
  menitFokus: 25,
});
console.log(situs.length); // aman, minimal array kosong
```

Kesalahan yang sering terjadi: lupa bahwa hasilnya objek. `const situs = await chrome.storage.sync.get("situs")` menghasilkan `{ situs: [...] }`, bukan array. Pakai destructuring seperti contoh di atas.

## set, remove, dan clear

`set` menerima objek dan **menggabungkan** kunci-kuncinya ke isi yang sudah ada. Kunci lain yang tidak disebut tidak berubah:

```js
await chrome.storage.local.set({ mode: "fokus" });
await chrome.storage.local.set({ berakhir: 1767601500000 });
// isi sekarang: { mode: "fokus", berakhir: 1767601500000 }
```

Untuk menambah item ke array, baca dulu, buat array baru, lalu simpan seluruh array:

```js
const { situs } = await chrome.storage.sync.get({ situs: [] });
if (!situs.includes("youtube.com")) {
  await chrome.storage.sync.set({ situs: [...situs, "youtube.com"] });
}
```

`remove("berakhir")` atau `remove(["mode", "berakhir"])` menghapus kunci tertentu, sedangkan `clear()` mengosongkan satu area. Nilai yang disimpan harus bisa diubah ke JSON, jadi jangan menyimpan fungsi, `Map`, atau objek `Date`. Simpan waktu sebagai angka milidetik.

## onChanged: popup dan worker tetap sinkron

Popup menampilkan sisa waktu, service worker yang mengubah mode saat alarm berbunyi. Bagaimana popup tahu kalau mode berubah saat ia sedang terbuka? Dengarkan `chrome.storage.onChanged`:

```js
chrome.storage.onChanged.addListener((changes, areaName) => {
  if (areaName === "local" && changes.mode) {
    const { oldValue, newValue } = changes.mode;
    labelMode.textContent = newValue;
  }
});
```

Parameter pertama berisi kunci yang berubah, masing-masing dengan `oldValue` dan `newValue`. Kunci baru tidak punya `oldValue`, kunci yang dihapus tidak punya `newValue`. Parameter kedua menyebut areanya: `"local"`, `"sync"`, atau `"session"`.

Pola ini membuat storage menjadi **satu sumber kebenaran**. Service worker menulis ke storage, popup dan halaman opsi membaca dan mendengarkan. Tidak ada bagian yang menyimpan salinan state sendiri yang bisa basi. Contohnya, saat pengguna menambah situs di halaman opsi, popup yang sedang terbuka langsung ikut memperbarui daftarnya.

## Menyimpan state timer

Misalnya kamu menyimpan timer sebagai sisa detik: `{ sisa: 1500 }`. Siapa yang mengurangi angka itu setiap detik? Service worker yang bisa tidur jelas tidak bisa. Popup juga tidak, karena hanya hidup selama terbuka.

Caranya dibalik: simpan **waktu berakhir**, lalu hitung sisa waktu kapan pun dibutuhkan.

```js
// saat mulai fokus
await chrome.storage.local.set({
  mode: "fokus",
  berakhir: Date.now() + 25 * 60_000,
});

// di popup, kapan pun dibuka
const { berakhir } = await chrome.storage.local.get("berakhir");
const sisaDetik = Math.ceil((berakhir - Date.now()) / 1000);
```

Angka `berakhir` tidak pernah berubah selama sesi. Service worker boleh tidur dan bangun berkali-kali, popup boleh dibuka dan ditutup, hasil hitungannya tetap benar karena hanya bergantung pada jam. Simpan juga `mode` di kunci yang sama supaya semua bagian tahu fase timer: `"diam"`, `"fokus"`, atau `"istirahat"`.

Ingat juga kasus tepi: kalau `berakhir` sudah lewat atau belum ada, sisa waktunya 0, bukan angka negatif. Pakai `Math.max(0, ...)`.

## Contoh: halaman opsi yang menyimpan situs

Supaya utuh, berikut potongan `options.js` yang menyimpan situs dari form dan menampilkan daftarnya. Semua yang dibahas bab ini terpakai: `get` dengan default, `set` seluruh array, dan `onChanged` untuk memperbarui tampilan.

```js
const form = document.querySelector("form");
const daftar = document.querySelector("#daftar");

function gambar(situs) {
  daftar.replaceChildren(...situs.map((s) => {
    const li = document.createElement("li");
    li.textContent = s;
    return li;
  }));
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();
  const domain = form.situs.value.trim().toLowerCase();
  const { situs } = await chrome.storage.sync.get({ situs: [] });
  if (domain && !situs.includes(domain)) {
    await chrome.storage.sync.set({ situs: [...situs, domain] });
  }
});

chrome.storage.onChanged.addListener((changes, area) => {
  if (area === "sync" && changes.situs) gambar(changes.situs.newValue ?? []);
});

chrome.storage.sync.get({ situs: [] }).then(({ situs }) => gambar(situs));
```

Kesalahan yang sering muncul di kode semacam ini:

- Memakai `push` lalu lupa memanggil `set`. Array hasil `get` hanyalah salinan, mengubahnya tidak mengubah storage.
- Menyimpan setiap situs sebagai kunci terpisah di `sync`. Batas 512 item dan kuota per item lebih mudah dijaga bila daftar disimpan sebagai satu array.
- Menganggap `set` langsung selesai. Ia mengembalikan Promise, jadi pakai `await` bila kode setelahnya bergantung pada data baru.

## Rangkuman

- `chrome.storage` menggantikan `localStorage` di ekstensi, butuh izin `"storage"`, asinkron, dan bisa dipakai dari semua bagian ekstensi.
- `local` (10 MB) untuk state di perangkat, `sync` (102.400 byte, 8.192 per item) untuk pengaturan yang ikut akun, `session` (memori) untuk data sementara.
- `get` mengembalikan objek; pakai objek default supaya kunci kosong terisi. `set` menggabungkan kunci, bukan mengganti semua isi.
- `chrome.storage.onChanged` memberi `changes` berisi `oldValue`/`newValue` dan nama area, sehingga popup dan service worker tetap sinkron.
- Simpan timer sebagai waktu `berakhir`, lalu hitung sisa dengan `berakhir - Date.now()` dan jangan biarkan negatif.

