solution.code:
async function ambilPengaturan() {
  return await chrome.storage.sync.get({ situs: [], menitFokus: 25 });
}

function normalkan(masukan) {
  return masukan
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, "")
    .replace(/^www\./, "")
    .split("/")[0];
}

async function tambahSitus(masukan) {
  const domain = normalkan(masukan);
  const { situs } = await chrome.storage.sync.get({ situs: [] });
  if (domain === "" || situs.includes(domain)) return situs;
  const baru = [...situs, domain];
  await chrome.storage.sync.set({ situs: baru });
  return baru;
}

async function sisaDetik() {
  const { berakhir } = await chrome.storage.local.get("berakhir");
  if (typeof berakhir !== "number") return 0;
  return Math.max(0, Math.ceil((berakhir - Date.now()) / 1000));
}

