solution.code:
async function tangani(pesan) {
  const { situs } = await chrome.storage.sync.get({ situs: [] });
  if (pesan.tipe === "daftar") return { ok: true, situs };
  if (pesan.tipe === "tambah") {
    if (typeof pesan.situs !== "string" || pesan.situs.trim() === "") return { ok: false };
    const domain = pesan.situs.trim().toLowerCase();
    if (situs.includes(domain)) return { ok: true, situs };
    const baru = [...situs, domain];
    await chrome.storage.sync.set({ situs: baru });
    return { ok: true, situs: baru };
  }
  return { ok: false };
}

function pasangPenangan() {
  chrome.runtime.onMessage.addListener((pesan, sender, sendResponse) => {
    if (typeof pesan !== "object" || pesan === null) {
      sendResponse({ ok: false });
      return;
    }
    tangani(pesan).then(sendResponse);
    return true;
  });
}

