solution.code:
function ringkasHalaman(paragraf) {
  let kata = 0;
  for (const p of paragraf) {
    kata += p.split(/\s+/).filter(Boolean).length;
  }
  return { kata, menit: Math.max(1, Math.ceil(kata / 200)) };
}

function sorot(teks, kata) {
  if (!kata) return [{ teks, sorot: false }];
  const kecil = teks.toLowerCase();
  const cari = kata.toLowerCase();
  const hasil = [];
  let awal = 0;
  let i = kecil.indexOf(cari);
  while (i !== -1) {
    if (i > awal) hasil.push({ teks: teks.slice(awal, i), sorot: false });
    hasil.push({ teks: teks.slice(i, i + cari.length), sorot: true });
    awal = i + cari.length;
    i = kecil.indexOf(cari, awal);
  }
  if (awal < teks.length) hasil.push({ teks: teks.slice(awal), sorot: false });
  return hasil;
}

