function teksBadge(sisaDetik) {
  if (sisaDetik <= 0) return "";
  if (sisaDetik >= 60) return Math.ceil(sisaDetik / 60) + "m";
  return Math.ceil(sisaDetik) + "s";
}

function pasangMenu() {
  chrome.runtime.onInstalled.addListener(() => {
    chrome.contextMenus.create({ id: "catat", title: "Simpan ke catatan", contexts: ["selection"] });
  });

  chrome.contextMenus.onClicked.addListener(async (info, tab) => {
    if (info.menuItemId !== "catat") return;
    const teks = (info.selectionText || "").trim();
    if (!teks) return;
    const { catatan } = await chrome.storage.local.get({ catatan: [] });
    catatan.push({ teks, waktu: Date.now() });
    await chrome.storage.local.set({ catatan });
    await chrome.action.setBadgeText({ text: String(catatan.length) });
  });
}

