solution.code:
function buatAturan(domains) {
  const unik = [];
  for (const d of domains) {
    const kecil = d.toLowerCase();
    if (!unik.includes(kecil)) unik.push(kecil);
  }
  return unik.map((domain, i) => ({
    id: i + 1,
    priority: 1,
    action: { type: "redirect", redirect: { extensionPath: "/blocked.html" } },
    condition: { requestDomains: [domain], resourceTypes: ["main_frame"] },
  }));
}

async function setelFokus(aktif, domains) {
  const lama = await chrome.declarativeNetRequest.getDynamicRules();
  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: lama.map((r) => r.id),
    addRules: aktif ? buatAturan(domains) : [],
  });
  return (await chrome.declarativeNetRequest.getDynamicRules()).length;
}

