  const c = { _jam: jam, _restart() { for (const e of semuaEvent) e._fs = []; } };
  const aturan = { dynamic: [], session: [] };
  const ubahAturan = (jenis) => async ({ removeRuleIds = [], addRules = [] } = {}) => {
    const sisa = aturan[jenis].filter((r) => !removeRuleIds.includes(r.id));
    const id = new Set(sisa.map((r) => r.id));
    for (const r of addRules) {
      if (!Number.isInteger(r.id) || r.id < 1) throw new Error("Rule id must be a positive integer");
      if (id.has(r.id)) throw new Error("Rule with id " + r.id + " does not have a unique ID.");
      id.add(r.id);
    }
    aturan[jenis] = [...sisa, ...salin(addRules)];
  };
  c.declarativeNetRequest = {
    MAX_NUMBER_OF_DYNAMIC_RULES: 30000,
    updateDynamicRules: ubahAturan("dynamic"),
    async getDynamicRules() { return salin(aturan.dynamic); },
    updateSessionRules: ubahAturan("session"),
    async getSessionRules() { return salin(aturan.session); },
  };
  return c;
})();

