solution.code:
function auditEkstensi(manifest, berkas) {
  const temuan = [];
  for (const [nama, isi] of Object.entries(berkas)) {
    if (nama.endsWith(".html") && /<script[^>]*\ssrc\s*=\s*["']?https?:\/\//i.test(isi)) {
      temuan.push(nama + ": skrip-remote");
    }
    if (nama.endsWith(".js") && /\beval\s*\(|\bnew\s+Function\s*\(/.test(isi)) {
      temuan.push(nama + ": eval");
    }
  }
  const host = manifest.host_permissions || [];
  if (host.includes("<all_urls>") || host.includes("*://*/*")) {
    temuan.push("manifest.json: semua-situs");
  }
  const csp = (manifest.content_security_policy || {}).extension_pages || "";
  if (csp.includes("'unsafe-eval'")) temuan.push("manifest.json: csp-longgar");
  return temuan;
}

